import itertools

def is_strong(n,s,pairs):
    m=2*n
    g=[[] for _ in range(m)]
    for i in range(m-1): g[i].append(i+1)
    for w,b in pairs:
        g[w].append(b)
    # Strong connectivity check via BFS each side
    # Use Floyd? small
    N=m
    # compute reachability via DFS
    def reach(u):
        seen=[False]*N
        stack=[u]; seen[u]=True
        while stack:
            x=stack.pop()
            for y in g[x]:
                if not seen[y]: seen[y]=True; stack.append(y)
        return seen
    for i in range(N):
        if not all(reach(i)):
            return False
    return True

