def solve(n,s,t):
    N=n+2
    start=s+'__'
    target=t
    if start[:n]==target:
        return 0
    def eidx(st):
        for i in range(N-1):
            if st[i]=='_' and st[i+1]=='_':
                return i
    q=deque([(start,0)])
    vis={start}
    while q:
        cur,d=q.popleft()
        e=eidx(cur)
        for i in range(N-1):
            if cur[i]=='_' or cur[i+1]=='_':
                continue
            if i==e: continue
            new=list(cur)
            new[e]=cur[i]
            new[e+1]=cur[i+1]
            new[i]='_'
            new[i+1]='_'
            ns=''.join(new)
            if ns not in vis:
                if ns[:n]==target:
                    return d+1
                vis.add(ns)
                q.append((ns,d+1))
    return -1

