def can_theory(n,x,y,s,t):
    g=gcd(x,y)
    if s.count('0')!=t.count('0'): return False
    fs=[0]*g
    ft=[0]*g
    for i,ch in enumerate(s):
        if ch=='0': fs[i%g]+=1
    for i,ch in enumerate(t):
        if ch=='0': ft[i%g]+=1
    return fs==ft

